package com.yuegang.zhihui.knowledge.application;import java.util.*;import org.springframework.jdbc.core.*;import org.springframework.scheduling.annotation.*;import org.springframework.transaction.support.*;
public final class KnowledgeExpiryJob{private final JdbcTemplate jdbc;private final TransactionTemplate tx;public KnowledgeExpiryJob(JdbcTemplate j,org.springframework.transaction.PlatformTransactionManager m){jdbc=j;tx=new TransactionTemplate(m);}@Scheduled(fixedDelayString="${ygh.knowledge.expiry-delay:60000}")public void expire(){for(Long id:jdbc.queryForList("SELECT id FROM knowledge_document WHERE status='PUBLISHED' AND expires_at IS NOT NULL AND expires_at<=NOW(6) LIMIT 100",Long.class))tx.executeWithoutResult(s->{if(jdbc.update("UPDATE knowledge_document SET status='EXPIRED',version=version+1 WHERE id=? AND status='PUBLISHED'",id)==1){jdbc.update("INSERT INTO knowledge_status_history(id,document_id,from_status,to_status,operator_id,reason) VALUES(?,?,'PUBLISHED','EXPIRED',0,'POLICY_EXPIRED')",next(),id);jdbc.update("INSERT INTO knowledge_index_job(id,document_id,index_version,job_type,status) VALUES(?,?,?,'DELETE','PENDING')",next(),id,"knowledge-expiry-"+System.currentTimeMillis());}});}private static long next(){return UUID.randomUUID().getMostSignificantBits()&Long.MAX_VALUE;}}
